-- Run this in Supabase SQL Editor.
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade, role text not null default 'visitor' check (role in ('admin','visitor')));
create or replace function public.is_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin'); $$;
create table if not exists public.news (id bigint generated by default as identity primary key, title text not null, category text, body text not null, published boolean not null default false, created_at timestamptz default now());
create table if not exists public.projects (id bigint generated by default as identity primary key, title text not null, category text, description text, url text, published boolean not null default false, created_at timestamptz default now());
create table if not exists public.reviews (id bigint generated by default as identity primary key, name text not null, service text, rating int check(rating between 1 and 5), message text not null, status text not null default 'pending', created_at timestamptz default now());
create table if not exists public.questions (id bigint generated by default as identity primary key, name text, question text not null, answer text, status text not null default 'pending', created_at timestamptz default now());
create table if not exists public.budgets (id bigint generated by default as identity primary key, name text not null, contact text not null, service text, budget text, details text, created_at timestamptz default now());
alter table public.profiles enable row level security;
alter table public.news enable row level security;
alter table public.projects enable row level security;
alter table public.reviews enable row level security;
alter table public.questions enable row level security;
alter table public.budgets enable row level security;
create policy "public reads published news" on public.news for select using (published or public.is_admin());
create policy "admin manages news" on public.news for all using (public.is_admin()) with check(public.is_admin());
create policy "public reads published projects" on public.projects for select using (published or public.is_admin());
create policy "admin manages projects" on public.projects for all using(public.is_admin()) with check(public.is_admin());
create policy "public reads approved reviews" on public.reviews for select using(status='approved' or public.is_admin());
create policy "public submits reviews" on public.reviews for insert with check(status='pending');
create policy "admin manages reviews" on public.reviews for all using(public.is_admin()) with check(public.is_admin());
create policy "public reads answered questions" on public.questions for select using(status='answered' or public.is_admin());
create policy "public submits questions" on public.questions for insert with check(status='pending');
create policy "admin manages questions" on public.questions for all using(public.is_admin()) with check(public.is_admin());
create policy "public submits budget requests" on public.budgets for insert with check(true);
create policy "admin reads budgets" on public.budgets for select using(public.is_admin());
create policy "admin manages profiles" on public.profiles for all using(id=auth.uid() or public.is_admin()) with check(id=auth.uid() or public.is_admin());
-- After creating your own Supabase Auth user, grant admin using its UUID:
